import numpy as np

# The sandbox has no network or API key, so embeddings come from a small
# deterministic stand-in for client.embeddings.create(...). Swap embed() for a
# real OpenAI call (model="text-embedding-3-small") when running online.
QUERY = 'AI and ML tutorials'
_MOCK_SIMILARITY = {
    'How to train a machine learning model': 0.8456,
    'Best restaurants in Chennai': 0.1203,
    'Deep learning neural network tutorial': 0.8234,
    'Cricket World Cup 2026 schedule': 0.0875,
    'Introduction to artificial intelligence': 0.8921,
}


def embed(text):
    if text == QUERY:
        return np.array([1.0, 0.0])
    s = _MOCK_SIMILARITY.get(text, 0.0)
    return np.array([s, np.sqrt(1.0 - s * s)])


def cosine_similarity(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))


def semantic_search(sentences, query, top_k=3):
    query_vec = embed(query)
    scored = []
    for sentence in sentences:
        score = cosine_similarity(query_vec, embed(sentence))
        scored.append((float(score), sentence))
    scored.sort(key=lambda pair: pair[0], reverse=True)
    return scored[:top_k]


sentences = [
    'How to train a machine learning model',
    'Best restaurants in Chennai',
    'Deep learning neural network tutorial',
    'Cricket World Cup 2026 schedule',
    'Introduction to artificial intelligence'
]

results = semantic_search(sentences, 'AI and ML tutorials', top_k=3)
for score, text in results:
    print(f'{score:.4f}: {text}')
